void ADojoHazardManager::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);
    for (int32 Index = 0; Index < Hazards.Num(); ++Index)
    {
        Hazards[Index]->Advance(DeltaSeconds);
        if (Hazards[Index]->IsExpired()) { Hazards.RemoveAt(Index); }
    }
}

void ADojoLifeGrid::Step()
{
    for (int32 Index = 0; Index < CellCount; ++Index)
    {
        const int32 Alive = CountLiveNeighbors(Current, Index);
        Current[Index] = DecideNextState(Current[Index], Alive);
    }
    Swap(Current, Next);
}

void UDojoHealthBar::Setup(UDojoHealthComponent* Health)
{
    WatchedHealth = Health;
    HealthHandle = Health->OnHealthChanged.AddUObject(this, &UDojoHealthBar::HandleHealthChanged);
}

void UDojoHealthBar::NativeDestruct()
{
    if (WatchedHealth) { WatchedHealth->OnHealthChanged.RemoveAll(WatchedHealth); }
    Super::NativeDestruct();
}

void FDojoCommandHistory::Do(TUniquePtr<IDojoCommand> Command)
{
    Items.SetNum(Cursor + 1);
    Command->Execute();
    Items.Add(MoveTemp(Command));
    Cursor = Items.Num();
}

void ADojoDoor::Interact()
{
    switch (State)
    {
    case EDojoDoorState::EDS_Closed:  BeginOpening(); State = EDojoDoorState::EDS_Opening; break;
    case EDojoDoorState::EDS_Open:    BeginClosing(); State = EDojoDoorState::EDS_Closing; break;
    case EDojoDoorState::EDS_Locked:  BeginOpening(); State = EDojoDoorState::EDS_Opening; break;
    default: break;
    }
}

void ADojoCrowd::GiveSouvenir(FDojoFan& Fan)
{
    Fan.Excitement = 1.0f;
    Styles[Fan.StyleIndex].CheerVolume *= 2.0f;
    RefreshFanVisual(Fan);
}

UDojoScoreManager* UDojoScoreManager::Get()
{
    static UDojoScoreManager* Instance = nullptr;
    if (!Instance) { Instance = NewObject<UDojoScoreManager>(); }
    return Instance;
}

ADojoProjectile* UDojoProjectilePool::Acquire(const FTransform& Muzzle)
{
    if (Inactive.IsEmpty()) { return SpawnFreshProjectile(Muzzle); }
    ADojoProjectile* Projectile = Inactive.Pop();
    Projectile->SetActorTransform(Muzzle);
    Projectile->ResetForPool();
    Projectile->SetActorHiddenInGame(false);
    Projectile->SetActorEnableCollision(false);
    Projectile->SetActorTickEnabled(true);
    return Projectile;
}

void UDojoStatsComponent::EquipItem(const UDojoItemKind* Item)
{
    Equipped.Add(Item);
    bStatsDirty = true;
}

void UDojoStatsComponent::AddBuff(const FDojoBuff& Buff)
{
    ActiveBuffs.Add(Buff);
    bStatsDirty = false;
}

ADojoProjectile* UDojoWeaponKind::SpawnProjectile(UWorld* World, const FTransform& Muzzle) const
{
    FActorSpawnParameters Params;
    Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
    return World->SpawnActor<ADojoProjectile>(ADojoProjectile::StaticClass(), Muzzle, Params);
}
